  httplib::Server svr;
  // Matches realistic deployments: X-Forwarded-For parsing runs only after
  // set_trusted_proxies is configured.
  svr.set_trusted_proxies({"127.0.0.1"});

  svr.Get("/", [](const httplib::Request &req, httplib::Response &res) {
    res.set_content(std::string("remote_addr=") + req.remote_addr,
