    svr.Get(".*", handler);
    svr.Post(".*", handler_with_content_reader);
    svr.Put(".*", handler_with_content_reader);
    svr.Patch(".*", handler_with_content_reader);
    svr.Delete(".*", handler_with_content_reader);
    svr.Options(".*", handler);

